root <- '/repo/项目代码/vcr-engine'; source(file.path(root,'R/engine.R')); vcr_engine_load(root); source(file.path(root,'tests/helpers/harness.R')); invisible(vcr_test_data_root())
d <- read.csv('/clinical/actg_survival.csv')
stopifnot(nrow(d)==2139, all(d$cens %in% c(0,1)), all(d$days>=0), !anyNA(d[,c('pidnum','age','wtkg','gender','cd40','treat','days','cens')]))
s <- data.frame(USUBJID=as.character(d$pidnum),arm=d$treat,age=d$age,wtkg=d$wtkg,gender=d$gender,cd40=d$cd40)
e <- data.frame(USUBJID=as.character(d$pidnum),PARAMCD='COMPOSITE',AVAL=d$days,CNSR=1L-d$cens)
a <- vcr_test_input(s,'snp_actg:subject','subject'); b <- vcr_test_input(e,'snp_actg:events','event')
sc <- list(tau=1000,treatmentColumn='arm',parameterCode='COMPOSITE',timeUnit='days')
r <- vcr_test_run(vcr_test_job('comparator.rmst',sc,list(a,b),job_id='job_actg_rmst'))
wsc <- c(sc,list(covariates=list('age','wtkg','gender','cd40'),endpoint=list(type='time_to_event'),estimand='ATT'))
w <- vcr_test_run(vcr_test_job('comparator.entropy_balance',wsc,list(a,b),job_id='job_actg_weighted',replicates=2000,cores=2))
writeLines(jsonlite::toJSON(list(n=nrow(d),events=sum(d$cens),endpoint='CD4 decline >=50%, AIDS progression or death',unit='days',result=r,weighted=w),auto_unbox=TRUE,null='null',na='null',digits=NA,pretty=TRUE),'/clinical/actg-result.json')
